// Example code in fetchGroceries.js:

module.exports = {
  getAll: function () {
    // Fetch all grocery records
    // Example code:
    const response = fetch('/groceries');
    return response.json();
  }
};

// Import necessary express middleware and functions.
const express = require('express');
const { findAll, findById, create, updateById } = require('../services/grocery_service');
import jsonParser from '../middleware/json_parser';

// Create an Express application instance.
const app = express();

/**
 * Retrieves all grocery items from the database and sends them as JSON response.
 */
app.get('/', (req, res) => {
  try {
    const groceryItems = findAll();
    if (!groceryItems.error) {
      res.send(jsonParser.parse(groceryItems));
    } else {
      res.status(405).send('Invalid grocery data');
    }
  } catch (error) {
    console.error('Error retrieving grocery items:', error);
    res.status(500).send('Internal server error');
  }
});

/**
 * Retrieves a grocery item by its ID and sends it as JSON response.
 */
app.get('/:id', (req, res) => {
  try {
    const grocery = findById(req.params.id);
    if (!grocery.error) {
      res.send(jsonParser.parse(grocery));
    } else {
      console.error('Error retrieving grocery item:', error);
      res.status(405).send('Invalid grocery data');
    }
  } catch (error) {
    console.error('Error retrieving grocery item:', error);
    res.status(500).send('Internal server error');
  }
});

/**
 * Creates a new grocery item and sends it as JSON response.
 */
app.post('/', jsonParser, (req, res) => {
  try {
    const grocery = create(req.body);
    if (!grocery.error) {
      res.status(201).send(jsonParser.parse(grocery));
    } else {
      console.error('Error creating grocery item:', error);
      res.status(405).send('Invalid grocery data');
    }
  } catch (error) {
    console.error('Error creating grocery item:', error);
    res.status(500).send('Internal server error');
  }
});

/**
 * Updates an existing grocery item and sends it as JSON response.
 */
app.put('/:id', jsonParser, (req, res) => {
  try {
    const grocery = updateById(req.params.id, req.body);
    if (!grocery.error) {
      res.status(200).send(jsonParser.parse(grocery));
    } else {
      console.error('Error updating grocery item:', error);
      res.status(405).send('Invalid grocery data');
    }
  } catch (error) {
    console.error('Error updating grocery item:', error);
    res.status(500).send('Internal server error');
  }
});

/**
 * Deletes a grocery item by its ID and sends it as JSON response.
 */
app.delete('/:id', jsonParser, (req, res) => {
  try {
    const grocery = findById(req.params.id);
    if (!grocery.error) {
      res.status(204).send(jsonParser.parse(grocery));
    } else {
      console.error('Error deleting grocery item:', error);
      res.status(405).send('Invalid grocery data');
    }
  } catch (error) {
    console.error('Error deleting grocery item:', error);
    res.status(500).send('Internal server error');
  }
});

// Export the Express application object.
module.exports = app;

