// File containing utility functions for validation.

const Joi = require('joi');

/**
 * Validates the given input data against a set of validation rules.
 *
 * @param {any} data - The input data to validate.
 * @returns {object} A Joi validation object with error messages and other properties for usage.
 */
function validateInput(data) {
  const rules = Joi.object({
    status: Joi.string().required(),
    success: Joi.bool().default(true),
    message: Joi.string().min(1).required(),
  });

  return rules.validate(data);
}

// Middleware to validate inputs before calling a route.
function validateResponse(req, res) {
  const { success } = req.body;

  if (!success && !res.error) {
    res.json({ error: 'Error' });
  }
}

// Middleware to validate inputs before calling a route.
function validateInputAndResponse(req, res) {
  const { success } = req.body;

  if (!success && !res.error) {
    res.json({ error: 'Error' });
  } else if (success && !res.error) {
    const { body: errors } = req.body;
    res.json({ success, messages: errors });
  }
}

// Middleware to validate inputs before calling a route.
function validateResponseAndMiddleware(req, res) {
  const { success } = req.body;

  if (!success && !res.error) {
    res.json({ error: 'Error' });
  } else if (success && !res.error) {
    const { body: errors, middleware } = req.body;
    res.json({ success, messages: errors, middleware });
  }
}

