const express = require('express');
const router = new express.Router();
const db = require('../db');

// GET /groceries
router.get('/', async (req, res) => {
  try {
    const allGroceries = await db.query('SELECT * FROM groceries');
    res.json(allGroceries.rows);
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// GET /groceries/:id
router.get('/:id', async (req, res) => {
  try {
    const { id } = req.params;
    const grocery = await db.query('SELECT * FROM groceries WHERE id = $1', [id]);
    if (grocery.rows.length === 0) {
      return res.status(404).json({ error: 'Grocery not found' });
    }
    res.json(grocery.rows[0]);
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// POST /groceries
router.post('/', async (req, res) => {
  try {
    const { name, quantity } = req.body;
    if (!name || !quantity) {
      return res.status(400).json({ error: 'Name and quantity are required' });
    }
    const newGrocery = await db.query('INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id', [name, quantity]);
    res.status(201).json({ id: newGrocery.rows[0].id });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// PUT /groceries/:id
router.put('/:id', async (req, res) => {
  try {
    const { id } = req.params;
    const { name, quantity } = req.body;
    if(!id || !name || !quantity) {
      return res.status(400).json({ error: 'Id, name and quantity are required' });
    }
    const updateGrocery = await db.query('UPDATE groceries SET name = $1, quantity = $2 WHERE id = $3 RETURNING *', [name, quantity, id]);
    if(updateGrocery.rows.length === 0) {
      return res.status(404).json({ error: 'Grocery not found' });
    }
    res.json(updateGrocery.rows[0]);
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// DELETE /groceries/:id
router.delete('/:id', async (req, res) => {
  try {
    const { id } = req.params;
    const deleteGrocery = await db.query('DELETE FROM groceries WHERE id = $1', [id]);
    if(deleteGrocery.rows.length === 0) {
      return res.status(404).json({ error: 'Grocery not found' });
    }
    res.json({ message: 'Grocery deleted successfully' });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

module.exports = router;

