const { Router } = require('express');

const router = new Router();

router.post('/', async (req, res) => {
  const { name, quantity } = req.body;
  if(!name || !quantity) {
    return res.status(400).send('Missing name or quantity');
  }
  const groceries = await db.readGroceries();
  const lastGrocery = groceries[ groceries.length - 1];
  const newId = lastGrocery ? lastGrocery.id + 1 : 1;
  const newGrocery = {
    id: newId,
    name,
    quantity
  };
  groceries.push(newGrocery);
  await db.writeGroceries(groceries);
  return res.status(201).json(newGrocery);
});

module.exports = router;

