// List all groceries
router.get('/', async (req, res) => {
  try {
    const result = await db.query('SELECT * FROM groceries');
    res.json(result.rows);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Get a grocery by ID
router.get('/:id', async (req, res) => {
  try {
    const result = await db.query('SELECT * FROM groceries WHERE id = $1', [req.params.id]);
    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Grocery not found' });
    }
    res.json(result.rows[0]);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Create a new grocery
router.post('/', async (req, res) => {
  try {
    const { name, quantity } = req.body;
    const result = await db.query('INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING *', [name, quantity]);
    res.status(201).json(result.rows[0]);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Update a grocery by ID
router.put('/:id', async (req, res) => {
  try {
    const { name, quantity } = req.body;
    const result = await db.query('UPDATE groceries SET name = $1, quantity = $2 WHERE id = $3 RETURNING *', [name, quantity, req.params.id]);
    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Grocery not found' });
    }
    res.json(result.rows[0]);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Delete a grocery by ID
router.delete('/:id', async (req, res) => {
  try {
    const result = await db.query('DELETE FROM groceries WHERE id = $1', [req.params.id]);
    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Grocery not found' });
