import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.*;

import java.util.List;
import java.util.Optional;

@RestController
@RequestMapping("/groceries")
public class GroceryController {

    @Autowired
    private GroceryRepository groceryRepository;

    @GetMapping
    public List<Grocery> list() {
        return groceryRepository.findAll();
    }

    @GetMapping("/{id}")
    public Optional<Grocery> get(@PathVariable Long id) {
        return groceryRepository.findById(id);
    }

    @PostMapping
    public Grocery create(@RequestBody Grocery grocery) {
        return groceryRepository.save(grocery);
    }

    @PutMapping("/{id}")
    public Grocery update(@PathVariable Long id, @RequestBody Grocery groceryDetails) {
        return groceryRepository.findById(id)
                .map(grocery -> {
                    grocery.setName(groceryDetails.getName());
                    grocery.setQuantity(groceryDetails.getQuantity());
                    return groceryRepository.save(grocery);
                })
                .orElseGet(() -> {
                    grocery.setId(id);
                    return groceryRepository.save(grocery);
                });
    }

    @DeleteMapping("/{id}")
    public void delete(@PathVariable Long id) {
        groceryRepository.deleteById(id);
    }
}

