const express = require('express');
const router = express.Router();
const Grocery = require('../models/grocery');

// List all groceries
router.get('/', async (req, res) => {
  const groceries = await Grocery.findAll();
  res.json(groceries);
});

// Get a grocery by ID
router.get('/:id', async (req, res) => {
  const grocery = await Grocery.findByPk(req.params.id);
  if (grocery) {
    res.json(grocery);
  } else {
    res.status(404).json({ error: 'Grocery not found' });
  }
});

// Create a new grocery
router.post('/', async (req, res) => {
  const { name, quantity } = req.body;
  const newGrocery = await Grocery.create({ name, quantity });
  res.status(201).json(newGrocery);
});

// Update a grocery by ID
router.put('/:id', async (req, res) => {
  const { name, quantity } = req.body;
  const updatedGrocery = await Grocery.findByPk(req.params.id);
  if (updatedGrocery) {
    updatedGrocery.name = name;
    updatedGrocery.quantity = quantity;
    await updatedGrocery.save();
    res.json(updatedGrocery);
  } else {
    res.status(404).json({ error: 'Grocery not found' });
  }
});

// Delete a grocery by ID
router.delete('/:id', async (req, res) => {
  const deletedGrocery = await Grocery.findByPk(req.params.id);
  if (deletedGrocery) {
    await deletedGrocery.destroy();
    res.status(204).send();
  } else {
    res.status(404).json({ error: 'Grocery not found' });
  }
});

module.exports = router;

