from django.http import JsonResponse
from django.views.decorators.csrf import csrf_exempt
from .models import Grocery

@csrf_exempt
def grocery_list(request):
    if request.method == 'GET':
        groceries = list(Grocery.objects.values())
        return JsonResponse(groceries, safe=False)

@csrf_exempt
def grocery_detail(request, pk):
    try:
        grocery = Grocery.objects.get(pk=pk)
    except Grocery.DoesNotExist:
        return JsonResponse({'error': 'Grocery not found'}, status=404)

    if request.method == 'GET':
        return JsonResponse(grocery)
    elif request.method == 'PUT':
        grocery.name = request.POST.get('name', grocery.name)
        grocery.quantity = request.POST.get('quantity', grocery.quantity)
        grocery.save()
        return JsonResponse(grocery)
    elif request.method == 'DELETE':
        grocery.delete()
        return JsonResponse({'success': True})

@csrf_exempt
def create_grocery(request):
    if request.method == 'POST':
        grocery = Grocery(name=request.POST.get('name'), quantity=request.POST.get('quantity'))
        grocery.save()
        return JsonResponse(grocery, status=201)

