import { Component, OnInit } from '@angular/core';
import { GroceryService } from './grocery.service';

@Component({
  selector: 'app-grocery',
  templateUrl: './grocery.component.html',
  styleUrls: ['./grocery.component.css']
})
export class GroceryComponent implements OnInit {
  groceries: any[] = [];
  selectedGrocery: any;

  constructor(private groceryService: GroceryService) {}

  ngOnInit(): void {
    this.getGroceries();
  }

  getGroceries() {
    this.groceryService.getGroceries().then(groceries => {
      this.groceries = groceries;
    });
  }

  getGroceryById(id: number) {
    this.groceryService.getGroceryById(id).then(grocery => {
      this.selectedGrocery = grocery;
    });
  }

  createGrocery(grocery: any) {
    this.groceryService.createGrocery(grocery).then(() => {
      this.getGroceries();
    });
  }

  updateGrocery(id: number, updatedGrocery: any) {
    this.groceryService.updateGrocery(id, updatedGrocery).then(() => {
      this.getGroceries();
    });
  }

  deleteGrocery(id: number) {
    this.groceryService.deleteGrocery(id).then(() => {
      this.getGroceries();
    });
  }
}

