import { Injectable } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';

@Injectable({
  providedIn: 'root'
})
export class GroceryService {
  private apiUrl = '/api/groceries';

  constructor(private http: HttpClient) {}

  getGroceries(): Promise<any[]> {
    return this.http.get(this.apiUrl).toPromise();
  }

  getGroceryById(id: number): Promise<any> {
    const params = new HttpParams().set('id', id.toString());
    return this.http.get(this.apiUrl, { params }).toPromise();
  }

  createGrocery(grocery: any): Promise<any> {
    return this.http.post(this.apiUrl, grocery).toPromise();
  }

  updateGrocery(id: number, updatedGrocery: any): Promise<any> {
    return this.http.put(`${this.apiUrl}/${id}`, updatedGrocery).toPromise();
  }

  deleteGrocery(id: number): Promise<any> {
    return this.http.delete(`${this.apiUrl}/${id}`).toPromise();
  }
}
